const fn provider(
    id: &'static str,
    name: &'static str,
    auth_name: &'static str,
    auth_variables: &'static [&'static str],
) -> ProviderSpec {
    ProviderSpec {
        id,
        name,
        auth_name,
        auth_variables,
    }
}

/// Returns every built-in text provider using the production reqwest transport.
pub fn builtin_providers() -> Vec<Arc<dyn Provider>> {
    let transport: DynHttpTransport = Arc::new(ReqwestTransport::default());
    let adapters = builtin_adapters();
    let mut providers = STATIC_PROVIDER_SPECS
        .iter()
        .map(|spec| {
            Arc::new(static_provider_with_adapters(
                spec,
                transport.clone(),
                &adapters,
            )) as Arc<dyn Provider>
        })
        .collect::<Vec<_>>();
    providers.push(Arc::new(RadiusProvider::new(
        "radius",
        "Radius",
        "https://radius.pi.dev",
        transport,
    )));
    providers
}

/// Flattens the static portion of the built-in text catalog.
pub fn builtin_models() -> Vec<Model> {
    model_catalog()
        .values()
        .flat_map(|models| models.values().cloned())
        .collect()
}

fn model_catalog() -> &'static ModelCatalog {
    MODEL_CATALOG.get_or_init(|| {
        serde_json::from_str(include_str!("model_catalog.generated.json"))
            .expect("generated Pi model catalog must deserialize")
    })
}

fn provider_models(provider_id: &str) -> Vec<Model> {
    model_catalog()
        .get(provider_id)
        .unwrap_or_else(|| panic!("generated Pi model catalog is missing provider {provider_id}"))
        .values()
        .cloned()
        .collect()
}

fn provider_spec(provider_id: &str) -> &'static ProviderSpec {
    STATIC_PROVIDER_SPECS
        .iter()
        .find(|spec| spec.id == provider_id)
        .unwrap_or_else(|| panic!("missing built-in provider specification for {provider_id}"))
}

fn static_provider(spec: &ProviderSpec, transport: DynHttpTransport) -> ProviderDescriptor {
    static_provider_with_adapters(spec, transport, &builtin_adapters())
}

fn static_provider_with_adapters(
    spec: &ProviderSpec,
    transport: DynHttpTransport,
    adapters: &BTreeMap<String, Arc<dyn WireAdapter>>,
) -> ProviderDescriptor {
    let models = provider_models(spec.id);
    let required_apis = models
        .iter()
        .map(|model| model.api.clone())
        .collect::<BTreeSet<_>>();
    let mut descriptor = ProviderDescriptor::new(
        spec.id,
        spec.name,
        env_auth(spec.auth_name, spec.auth_variables.iter().copied()),
        models,
    )
    .with_transport(transport);
    for api in required_apis {
        descriptor = descriptor.with_adapter(
            adapters
                .get(&api)
                .unwrap_or_else(|| panic!("missing wire adapter for generated Pi API {api}"))
                .clone(),
        );
    }
    descriptor
}

/// Concrete adapters shipped by the crate, keyed by API id.
pub fn builtin_adapters() -> BTreeMap<String, Arc<dyn WireAdapter>> {
    [
        Arc::new(AnthropicMessagesAdapter) as Arc<dyn WireAdapter>,
        Arc::new(OpenAiCompletionsAdapter),
        Arc::new(OpenAiResponsesAdapter),
        Arc::new(OpenAiCodexAdapter),
        Arc::new(AzureOpenAiResponsesAdapter::default()),
        Arc::new(GoogleGenerativeAiAdapter),
        Arc::new(GoogleVertexAdapter),
        Arc::new(MistralConversationsAdapter),
        Arc::new(BedrockConverseStreamAdapter),
        Arc::new(PiMessagesAdapter),
    ]
    .into_iter()
    .map(|adapter| (adapter.api().to_owned(), adapter))
    .collect()
}

/// Anthropic descriptor and catalog.
pub fn anthropic_provider(transport: DynHttpTransport) -> ProviderDescriptor {
    static_provider(provider_spec("anthropic"), transport)
}

/// `OpenAI` descriptor using Pi's current Responses catalog.
pub fn openai_provider(transport: DynHttpTransport) -> ProviderDescriptor {
    static_provider(provider_spec("openai"), transport)
}

/// Google Gemini API descriptor.
pub fn google_provider(transport: DynHttpTransport) -> ProviderDescriptor {
    static_provider(provider_spec("google"), transport)
}

/// Vertex descriptor for app-supplied project/location model URLs.
pub fn google_vertex_provider(
    base_url: impl Into<String>,
    mut models: Vec<Model>,
    transport: DynHttpTransport,
) -> ProviderDescriptor {
    let base_url = base_url.into();
    for model in &mut models {
        model.provider = "google-vertex".into();
        model.api = "google-vertex".into();
        model.base_url.clone_from(&base_url);
    }
    ProviderDescriptor::new(
        "google-vertex",
        "Google Vertex AI",
        env_auth(
            "Google Vertex credential",
            ["GOOGLE_VERTEX_API_KEY", "GOOGLE_VERTEX_ACCESS_TOKEN"],
        ),
        models,
    )
    .with_transport(transport)
    .with_adapter(Arc::new(GoogleVertexAdapter))
}

