/// Azure Responses descriptor for app-supplied deployment endpoints/models.
pub fn azure_openai_provider(
    base_url: impl Into<String>,
    mut models: Vec<Model>,
    transport: DynHttpTransport,
) -> ProviderDescriptor {
    let base_url = base_url.into();
    for model in &mut models {
        model.provider = "azure-openai".into();
        model.api = "azure-openai-responses".into();
        model.base_url.clone_from(&base_url);
    }
    ProviderDescriptor::new(
        "azure-openai",
        "Azure OpenAI",
        env_auth("Azure OpenAI API key", ["AZURE_OPENAI_API_KEY"]),
        models,
    )
    .with_transport(transport)
    .with_adapter(Arc::new(AzureOpenAiResponsesAdapter::default()))
}

