fn image_model(id: &str, name: &str, text_output: bool, cost: ModelCostRates) -> ImageModel {
    ImageModel {
        id: id.into(),
        name: name.into(),
        api: "openrouter-images".into(),
        provider: "openrouter".into(),
        base_url: "https://openrouter.ai/api/v1".into(),
        input: vec![ModelInput::Text, ModelInput::Image],
        output: if text_output {
            vec![ModelInput::Image, ModelInput::Text]
        } else {
            vec![ModelInput::Image]
        },
        cost: cost.into(),
        headers: BTreeMap::new(),
    }
}

const fn rates(input: f64, output: f64, cache_read: f64, cache_write: f64) -> ModelCostRates {
    ModelCostRates {
        input,
        output,
        cache_read,
        cache_write,
    }
}

fn env_auth<'a>(name: &str, variables: impl IntoIterator<Item = &'a str>) -> ProviderAuth {
    ProviderAuth::api_key(Arc::new(EnvApiKeyAuth::new(name, variables)))
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct RadiusConfig {
    base_url: String,
    models: Vec<RadiusModel>,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct RadiusModel {
    id: String,
    name: String,
    reasoning: bool,
    #[serde(default)]
    thinking_level_map: BTreeMap<ThinkingLevel, Option<String>>,
    input: Vec<ModelInput>,
    cost: ModelCost,
    context_window: u64,
    max_tokens: u64,
}

/// Dynamic Radius provider speaking pi-messages end-to-end.
pub struct RadiusProvider {
    id: String,
    name: String,
    gateway: String,
    auth: ProviderAuth,
    models: RwLock<Vec<Model>>,
    transport: DynHttpTransport,
    adapter: Arc<PiMessagesAdapter>,
}

impl std::fmt::Debug for RadiusProvider {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("RadiusProvider")
            .field("id", &self.id)
            .field("name", &self.name)
            .field("gateway", &self.gateway)
            .field("auth", &self.auth)
            .field("models", &self.models.read())
            .field("transport", &self.transport)
            .field("adapter", &self.adapter)
            .finish()
    }
}

impl RadiusProvider {
    /// Creates a dynamic Radius provider.
    pub fn new(
        id: impl Into<String>,
        name: impl Into<String>,
        gateway: impl Into<String>,
        transport: DynHttpTransport,
    ) -> Self {
        Self {
            id: id.into(),
            name: name.into(),
            gateway: gateway.into().trim_end_matches('/').to_owned(),
            auth: env_auth("Radius API key", ["RADIUS_API_KEY"]),
            models: RwLock::new(Vec::new()),
            transport,
            adapter: Arc::new(PiMessagesAdapter),
        }
    }
}

#[async_trait]
impl Provider for RadiusProvider {
    fn id(&self) -> &str {
        &self.id
    }

    fn name(&self) -> &str {
        &self.name
    }

    fn auth(&self) -> &ProviderAuth {
        &self.auth
    }

    fn models(&self) -> Vec<Model> {
        self.models.read().clone()
    }

    fn is_dynamic(&self) -> bool {
        true
    }

    async fn refresh_models(
        &self,
        auth: &AuthResult,
        options: &RefreshOptions,
    ) -> Result<(), AiError> {
        if !options.allow_network {
            return Ok(());
        }
        if options
            .cancellation
            .as_ref()
            .is_some_and(tokio_util::sync::CancellationToken::is_cancelled)
        {
            return Err(AiError::Aborted);
        }
        let url = Url::parse(&format!("{}/v1/config", self.gateway))
            .map_err(|error| AiError::Validation(error.to_string()))?;
        let mut headers = HttpHeaders::from([("accept".into(), "application/json".into())]);
        if let Some(api_key) = &auth.auth.api_key {
            headers.insert("authorization".into(), format!("Bearer {api_key}"));
        }
        for (name, value) in &auth.auth.headers {
            if let Some(value) = value {
                headers.insert(name.clone(), value.clone());
            } else {
                headers.remove(name);
            }
        }
        let response = self
            .transport
            .execute(HttpRequest {
                method: http::Method::GET,
                url,
                headers,
                body: Bytes::new(),
                timeout: None,
                cancellation: options.cancellation.clone(),
            })
            .await?;
        let config: RadiusConfig = response.json()?;
        let models = config
            .models
            .into_iter()
            .map(|entry| Model {
                id: entry.id,
                name: entry.name,
                api: "pi-messages".into(),
                provider: self.id.clone(),
                base_url: config.base_url.clone(),
                reasoning: entry.reasoning,
                thinking_level_map: entry.thinking_level_map,
                input: entry.input,
                cost: entry.cost,
                context_window: entry.context_window,
                max_tokens: entry.max_tokens,
                headers: BTreeMap::new(),
                compat: None,
            })
            .collect();
        *self.models.write() = models;
        Ok(())
    }

    fn stream(
        &self,
        model: Model,
        context: Context,
        options: WireRequestOptions,
    ) -> AssistantEventStream {
        execute_text_stream(
            self.transport.clone(),
            self.adapter.clone(),
            model,
            context,
            options,
        )
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn builtins_have_unique_provider_and_model_ids() {
        let providers = builtin_providers();
        let mut provider_ids = std::collections::HashSet::new();
        for provider in providers {
            assert!(provider_ids.insert(provider.id().to_owned()));
            let mut model_ids = std::collections::HashSet::new();
            for model in provider.models() {
                assert_eq!(model.provider, provider.id());
                assert!(model_ids.insert(model.id));
            }
        }
    }

    #[test]
    fn generated_catalog_matches_current_pi_snapshot() {
        let catalog = model_catalog();
        assert_eq!(catalog.len(), 37);
        assert_eq!(builtin_models().len(), 1_109);
        assert_eq!(catalog["amazon-bedrock"].len(), 114);
        assert_eq!(catalog["anthropic"].len(), 15);
        assert_eq!(catalog["openai"].len(), 38);
        assert_eq!(catalog["openai-codex"].len(), 7);
        assert_eq!(catalog["openrouter"].len(), 276);
        assert_eq!(catalog["vercel-ai-gateway"].len(), 192);
        assert!(
            catalog["openai"]
                .values()
                .all(|model| model.api == "openai-responses")
        );
    }

    #[test]
    fn adapter_catalog_covers_required_text_protocols() {
        let adapters = builtin_adapters();
        for api in [
            "anthropic-messages",
            "openai-completions",
            "openai-responses",
            "openai-codex-responses",
            "azure-openai-responses",
            "google-generative-ai",
            "google-vertex",
            "mistral-conversations",
            "bedrock-converse-stream",
            "pi-messages",
        ] {
            assert!(adapters.contains_key(api), "missing {api}");
        }
    }

    #[test]
    fn image_catalog_matches_openrouter_wire_contract() {
        let models = builtin_image_models();
        assert!(!models.is_empty());
        assert!(models.iter().all(|model| {
            model.provider == "openrouter"
                && model.api == "openrouter-images"
                && model.output.contains(&ModelInput::Image)
        }));
    }
}
